// ═══════════════════════════════════════════════════════════════
//  COMIC / MANGÁ TOGGLE
//  Tema alternativo: quadrinho/mangá envelhecido em sépia,
//  com feathering, retícula e contornos de espessura variável.
//  Segue o mesmo padrão de sepia-toggle.js / hud-toggle.js:
//  - toggleComic() liga/desliga via classe no <body>
//  - persiste em localStorage
//  - applyComicToElement(el) é chamado pelo openApp() em cada
//    nova janela criada, para garantir que o filtro de feathering
//    seja reaplicado mesmo que o elemento seja inserido depois
//    do toggle já estar ativo (o CSS via body.comic-mode já cobre
//    isso automaticamente, mas mantemos a função para consistência
//    com os outros temas e para eventuais ajustes futuros).
//
//  As fontes do tema (Bangers + Comic Neue) ficam embutidas aqui
//  como base64 (@font-face), em vez de no <style> do index.html,
//  para manter o HTML principal mais leve e legível. São injetadas
//  uma única vez, no carregamento deste script, via <style> próprio,
//  para que já estejam disponíveis no momento em que o toggle for
//  ativado (sem flash de fonte errada).
// ═══════════════════════════════════════════════════════════════

(function () {
  // ── Injeta as fontes do tema (uma única vez) ──
  function injetarFontesComic() {
    if (document.getElementById('comic-fonts-style')) return; // já injetado
    const style = document.createElement('style');
    style.id = 'comic-fonts-style';
    style.textContent = `
    @font-face {
      font-family: 'Bangers';
      font-style: normal;
      font-weight: 400;
      font-display: swap;
      src: url(data:font/woff2;base64,) format('woff2');
    }
    @font-face {
      font-family: 'Comic Neue';
      font-style: normal;
      font-weight: 400;
      font-display: swap;
      src: url(data:font/woff2;base64,) format('woff2');
    }
    @font-face {
      font-family: 'Comic Neue';
      font-style: normal;
      font-weight: 700;
      font-display: swap;
      src: url(data:font/woff2;base64,) format('woff2');
    }
`;
    document.head.appendChild(style);
  }

  injetarFontesComic();

  function aplicarEstadoComic(ativo) {
    document.body.classList.toggle('comic-mode', ativo);
  }

  // Restaura o estado salvo ao carregar
  const salvo = localStorage.getItem('comicMode') === '1';
  if (salvo) aplicarEstadoComic(true);

  window.toggleComic = function () {
    const ativo = !document.body.classList.contains('comic-mode');
    aplicarEstadoComic(ativo);
    localStorage.setItem('comicMode', ativo ? '1' : '0');
  };

  // Chamado pelo openApp() para cada janela nova (mantém consistência
  // com applySepiaToElement / applyGreyToElement já usados no kernel)
  window.applyComicToElement = function (el) {
    if (!el) return;
    // O efeito é controlado inteiramente via CSS (body.comic-mode .window),
    // então não há classe própria a adicionar no elemento — esta função
    // existe para simetria com os outros toggles e por segurança caso
    // o tema evolua para precisar de ajustes por-janela no futuro.
  };
})();
